// OS Paging/Disk Caching via Memory Mapping (POSIX)

int fd = open("persistent_data.dat", O_RDWR);
size_t file_size = 1024 * 1024 * 100; // 100MB

// Map disk file directly into virtual memory
void *mem_region = mmap(NULL, file_size, 
                        PROT_READ | PROT_WRITE, 
                        MAP_SHARED, fd, 0);

// Accessing mem_region triggers demand paging (Disk -> RAM)
((int*)mem_region)[0] = 42; 

// Hint to the kernel about access pattern (optional optimization)
madvise(mem_region, file_size, MADV_SEQUENTIAL);

// Force modified ("dirty") pages back to disk
msync(mem_region, file_size, MS_SYNC);

munmap(mem_region, file_size);
close(fd);
